+            facets.push(Triangle::new(a, b, c));
+            facets.push(Triangle::new(a, c, d));
+        };
+        for i in 0..4 {
+            let j = (i + 1) % 4;
+            let (a, b, c, d) = (outer[i], outer[j], inner[j], inner[i]);
+            quad(v(a, 20.), v(b, 20.), v(c, 20.), v(d, 20.));
+            quad(v(d, 0.), v(c, 0.), v(b, 0.), v(a, 0.));
+            quad(v(a, 0.), v(b, 0.), v(b, 20.), v(a, 20.));
