+fn punch() -> AgieJob {
+    AgieJob {
+        quality: AgieQuality::FineRa030,
+        side: AgieSide::Punch,
+        round_profile: None,
+        contour: vec![[-20., -10.], [20., -10.], [20., 10.], [-20., 10.]],
+        start: Some([-30., 0.]),
+        stock_min: [-40., -30., -20.],
+        stock_max: [40., 30., 0.],
+    }
